UPDATE mrp_calc_batch SET status='READY_TO_CALCULATE', version=version+1
WHERE id=#{id} AND version=#{expectedVersion}
  AND active_run_id <=> #{expectedActiveRunId,jdbcType=BIGINT}
  AND status IN ('CALCULATING', 'WAITING_DAILY_DISTRIBUTION', 'WRITING', 'FAILED')

UPDATE mrp_calc_batch SET status=#{status}, version=version+1
WHERE id=#{id} AND status='CALCULATING'
  AND active_run_id <=> #{runId,jdbcType=BIGINT}

