        AND status = #{status}


        AND (factory_code LIKE CONCAT('%', #{keyword}, '%')
        OR id LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY created_at DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM mrp_calc_batch
AND status = #{status}
AND (factory_code LIKE CONCAT('%', #{keyword}, '%') OR id LIKE CONCAT('%', #{keyword}, '%'))

SELECT d.*, s.business_month AS business_month
FROM mrp_batch_business_week_scope s
JOIN business_week_detail d ON d.version_id=s.business_week_version_id
WHERE s.batch_id=#{batchId}
  AND d.end_date >= #{startDate}
  AND d.start_date <= #{endDate}
ORDER BY d.start_date, d.sort_no

